import java.util.Set;
import java.util.stream.Collectors;

public final class GameOfLife {

    private GameOfLife() {
    }

    public static Set<Cell> nextGeneration(Set<Cell> livingCells) {
        return livingCells.stream()
                .filter(cell -> survives(livingNeighbourCount(cell, livingCells)))
                .collect(Collectors.toUnmodifiableSet());
    }

    private static boolean survives(long livingNeighbours) {
        return livingNeighbours == 2;
    }

    private static long livingNeighbourCount(Cell cell, Set<Cell> livingCells) {
        return cell.neighbours().stream().filter(livingCells::contains).count();
    }
}
