    @Disabled("TODO: cell is a value type: Cell(1,2) equals Cell(1,2) and has the same hashCode, and differs from Cell(2,1)")
    @Test
    void cellIsAValueTypeWithEqualityByCoordinates() {
        // Add the observation when this behavior enters Red.
    }
}
